(function(){'use strict';
const target=window.VPQ_PHARM_EXAM2_PDF_PRACTICE||(window.VPQ_PHARM_EXAM2_PDF_PRACTICE=[]);
const bank=[{"id":"pharm-e2-user-diabetes-mcq-001","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #1","q":"Why does glucose require a specific membrane transporter to enter most cells?","options":["Glucose is a lipid-soluble molecule that requires enzymatic activation.","Glucose is water-soluble and cannot readily diffuse through the lipid bilayer.","Glucose is too large to enter cells through membrane proteins.","Glucose must first bind to circulating insulin to cross the membrane."],"answer":1,"why":"Glucose is polar, so it cannot diffuse efficiently across the lipid bilayer. GLUT transporters provide facilitated entry down a concentration gradient; insulin-dependent GLUT4 recruitment increases uptake in muscle and adipose tissue.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":1,"originalImportedWhy":"Uploaded answer key: Glucose is water-soluble and cannot readily diffuse through the lipid bilayer.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-002","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #2","q":"Which sequence best describes the effects of insulin binding to its receptor, as presented in the lecture?","options":["Insulin binding → inhibition of GLUT4 → decreased cellular glucose uptake.","Insulin binding → closure of calcium channels → glucose secretion.","Insulin binding → glucagon activation → hepatic glucose production.","Insulin binding → receptor activation → intracellular signaling → increased GLUT4 membrane association → glucose uptake."],"answer":3,"why":"The insulin receptor is a receptor tyrosine kinase. Activation initiates PI3K–Akt signaling, which recruits GLUT4 vesicles to the surface of muscle and adipose cells; insulin itself does not transport glucose.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":2,"originalImportedWhy":"Uploaded answer key: Insulin binding → receptor activation → intracellular signaling → increased GLUT4 membrane association → glucose uptake.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-003","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #3","q":"Which pancreatic islet cell is primarily responsible for insulin production and secretion?","options":["Beta cell","Alpha cell","Delta cell","Acinar cell"],"answer":0,"why":"Uploaded answer key: Beta cell","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":3},{"id":"pharm-e2-user-diabetes-mcq-004","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #4","q":"What is the primary physiologic stimulus for insulin secretion?","options":["Sympathetic alpha-2 receptor activation","Somatostatin release","Increased circulating glucose","Decreased circulating amino acids"],"answer":2,"why":"Uploaded answer key: Increased circulating glucose","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":4},{"id":"pharm-e2-user-diabetes-mcq-005","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #5","q":"Following glucose entry into a pancreatic beta cell, which event directly initiates membrane depolarization?","options":["Opening of ATP-sensitive potassium channels","Closure of ATP-sensitive potassium channels following increased ATP production","Activation of glucagon receptors","Inhibition of calcium influx"],"answer":1,"why":"Glucose metabolism increases the ATP/ADP ratio, which closes ATP-sensitive K⁺ channels. Reduced K⁺ efflux depolarizes the beta-cell membrane and allows voltage-gated calcium channels to open.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":5,"originalImportedWhy":"Uploaded answer key: Closure of ATP-sensitive potassium channels following increased ATP production","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-006","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #6","q":"Which event immediately precedes exocytosis of stored insulin granules?","options":["Activation of somatostatin receptors","Increased potassium efflux","Decreased intracellular ATP","Calcium influx through voltage-dependent calcium channels"],"answer":3,"why":"Depolarization opens voltage-gated calcium channels. Intracellular calcium is the immediate signal for insulin-containing secretory granules to fuse with the membrane.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":6,"originalImportedWhy":"Uploaded answer key: Calcium influx through voltage-dependent calcium channels","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-007","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #7","q":"Which glucose transporter is identified in the lecture as responsible for glucose entry into pancreatic beta cells?","options":["GLUT2","GLUT4","SGLT2","GLUT1"],"answer":0,"why":"Pancreatic beta cells respond to glucose metabolism, which raises ATP and closes KATP channels, triggering voltage-dependent calcium influx and insulin exocytosis. The uploaded lecture identifies GLUT2 as the glucose transporter, but transporter expression varies by species and glucose-sensing should not be reduced to GLUT2 alone.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":7,"originalImportedQuestion":"Which glucose transporter is identified in the lecture as responsible for glucose entry into pancreatic beta cells?","originalImportedAnswer":"GLUT2","originalImportedWhy":"Uploaded answer key: GLUT2"},{"id":"pharm-e2-user-diabetes-mcq-008","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #8","q":"Which combination of factors inhibits insulin secretion?","options":["Glucose, amino acids, and parasympathetic stimulation","Glucagon, fatty acids, and gastrointestinal hormones","Somatostatin, sympathetic alpha-2 stimulation, and insulin feedback","Calcium influx, ATP production, and glucose metabolism"],"answer":2,"why":"Somatostatin and alpha-2 adrenergic signaling inhibit beta-cell insulin release. This is why stress and autonomic drugs can modify glycemic physiology even before considering exogenous insulin.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":8,"originalImportedWhy":"Uploaded answer key: Somatostatin, sympathetic alpha-2 stimulation, and insulin feedback","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-009","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #9","q":"Somatostatin can inhibit insulin secretion through which mechanisms?","options":["Direct stimulation of beta cells and indirect activation of glucagon","Direct inhibition of beta cells and indirect effects through alpha cells","Activation of GLUT4 and inhibition of GLUT2","Increased glucose metabolism and calcium influx"],"answer":1,"why":"Somatostatin acts at inhibitory G-protein-coupled receptors on islet cells, reducing secretory signaling; it can also affect neighboring alpha-cell glucagon output.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":9,"originalImportedWhy":"Uploaded answer key: Direct inhibition of beta cells and indirect effects through alpha cells","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-010","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #10","q":"Which mechanisms naturally reduce insulin receptor signaling or insulin activity?","options":["Increased glucagon secretion and beta-cell proliferation","Increased GLUT4 expression and insulin synthesis","Increased intestinal glucose absorption","Insulin receptor desensitization and intracellular insulin degradation"],"answer":3,"why":"Repeated receptor activation can produce reduced receptor responsiveness, while insulin internalization and degradation terminate signaling. Insulin resistance may reflect defects after receptor binding, not simply receptor absence.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":10,"originalImportedWhy":"Uploaded answer key: Insulin receptor desensitization and intracellular insulin degradation","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-011","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #11","q":"Which metabolic response is consistent with the normal actions of insulin?","options":["Increased glucose uptake and glycogen formation","Increased hepatic glucose production and lipolysis","Decreased cellular glucose utilization","Increased ketone production and protein catabolism"],"answer":0,"why":"Uploaded answer key: Increased glucose uptake and glycogen formation","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":11},{"id":"pharm-e2-user-diabetes-mcq-012","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #12","q":"What best distinguishes absolute insulin deficiency from insulin-resistant diabetes?","options":["Type 1 involves glucagon deficiency, while Type 2 involves excessive glucagon.","Type 1 affects only dogs, while Type 2 affects only cats.","Type 1 involves deficient insulin production, while Type 2 involves inadequate tissue responsiveness to insulin.","Type 1 is caused by obesity, while Type 2 is always caused by pancreatic destruction."],"answer":2,"why":"Insulin deficiency reflects inadequate beta-cell secretion; insulin resistance means target tissues respond poorly to available insulin. Clinical type-2-like diabetes frequently combines resistance with progressive beta-cell dysfunction, especially in cats.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":12,"originalImportedQuestion":"What is the primary pathophysiologic difference between Type 1 and Type 2 diabetes mellitus?","originalImportedAnswer":"Type 1 involves deficient insulin production, while Type 2 involves inadequate tissue responsiveness to insulin.","originalImportedWhy":"Uploaded answer key: Type 1 involves deficient insulin production, while Type 2 involves inadequate tissue responsiveness to insulin."},{"id":"pharm-e2-user-diabetes-mcq-013","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #13","q":"Which organ systems are specifically emphasized as targets of hyperglycemia-associated damage?","options":["Skin, skeletal muscle, and gastrointestinal tract","Kidneys, cardiovascular system, and brain","Liver, spleen, and lymph nodes exclusively","Reproductive tract, pancreas, and thyroid exclusively"],"answer":1,"why":"Uploaded answer key: Kidneys, cardiovascular system, and brain","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":13},{"id":"pharm-e2-user-diabetes-mcq-014","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #14","q":"A diabetic dog presents with polyuria and polydipsia. Which mechanism best explains these findings?","options":["Insulin directly stimulates renal water excretion.","Glucagon inhibits renal sodium reabsorption.","Somatostatin stimulates urinary glucose secretion.","Glucose in the renal filtrate produces osmotic diuresis, increasing water loss."],"answer":3,"why":"When filtered glucose exceeds tubular reabsorptive capacity, glucose remains in urine and retains water osmotically. Urine volume rises and compensatory thirst develops, producing PU/PD.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":14,"originalImportedWhy":"Uploaded answer key: Glucose in the renal filtrate produces osmotic diuresis, increasing water loss.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-015","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #15","q":"Why may an untreated diabetic animal lose weight despite having an increased appetite?","options":["Inadequate insulin activity prevents efficient glucose utilization and promotes breakdown of energy stores.","Increased insulin secretion causes excessive fat deposition.","Glucose is converted exclusively into glycogen.","Decreased glucagon secretion prevents nutrient absorption."],"answer":0,"why":"Without adequate insulin action, glucose remains poorly available to insulin-dependent tissues despite hyperglycemia. Lipolysis and proteolysis supply energy, so body condition declines even with polyphagia.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":15,"originalImportedWhy":"Uploaded answer key: Inadequate insulin activity prevents efficient glucose utilization and promotes breakdown of energy stores.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-016","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #16","q":"Which clinical finding is particularly associated with diabetes mellitus in cats?","options":["Hyperextension of the carpus","Generalized muscle rigidity","Plantigrade stance associated with peripheral neuropathy","Persistent head tilt"],"answer":2,"why":"Chronic hyperglycemia can damage peripheral nerves in cats. Weakness in the distal pelvic limbs causes dropped hocks and a plantigrade stance; improvement may follow better diabetic regulation.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":16,"originalImportedWhy":"Uploaded answer key: Plantigrade stance associated with peripheral neuropathy","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-017","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #17","q":"What is the primary metabolic mechanism underlying diabetic ketoacidosis?","options":["Excessive insulin stimulates hepatic ketogenesis.","Insufficient insulin promotes fat mobilization and hepatic ketone production.","Excessive GLUT4 activity increases ketone production.","Somatostatin directly converts glucose into ketones."],"answer":1,"why":"Insulin deficiency removes inhibition of hormone-sensitive lipase and ketogenesis. The liver converts mobilized fatty acids into acidic ketones, while glucosuria worsens dehydration and total-body electrolyte loss.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":17,"originalImportedWhy":"Uploaded answer key: Insufficient insulin promotes fat mobilization and hepatic ketone production.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-018","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #18","q":"Which description best represents the typical diabetic pathophysiology in dogs according to the lecture?","options":["Reversible insulin receptor desensitization due exclusively to obesity","Excessive insulin secretion from pancreatic tumors","Temporary insulin resistance caused by dietary carbohydrate intake","Irreversible pancreatic beta-cell damage resulting in insulin deficiency"],"answer":3,"why":"Uploaded answer key: Irreversible pancreatic beta-cell damage resulting in insulin deficiency","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":18},{"id":"pharm-e2-user-diabetes-mcq-019","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #19","q":"What combination best characterizes typical feline type-2-like diabetes?","options":["Insulin resistance combined with variable pancreatic beta-cell dysfunction, often associated with obesity","Complete congenital absence of pancreatic beta cells","Excessive insulin receptor activation","Autoimmune destruction of pancreatic alpha cells"],"answer":0,"why":"Feline diabetes commonly involves peripheral insulin resistance and impaired beta-cell insulin secretion. Obesity is an important risk factor, but diabetes is not simply receptor desensitization, and lean cats can be affected.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":19,"originalImportedQuestion":"What is the predominant mechanism associated with Type 2 diabetes mellitus in cats?","originalImportedAnswer":"Obesity-associated insulin receptor desensitization and decreased insulin responsiveness","originalImportedWhy":"Uploaded answer key: Obesity-associated insulin receptor desensitization and decreased insulin responsiveness"},{"id":"pharm-e2-user-diabetes-mcq-020","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #20","q":"Why is early treatment of feline Type 2 diabetes particularly important?","options":["Cats cannot develop permanent pancreatic damage.","Insulin resistance always resolves without treatment.","Prolonged hyperglycemia can damage beta cells, reducing the likelihood of remission.","Hyperglycemia permanently increases insulin receptor sensitivity."],"answer":2,"why":"Persistent hyperglycemia causes glucotoxic beta-cell dysfunction. Early glycemic management can improve residual insulin secretion and insulin sensitivity, giving some cats a better chance of remission.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":20,"originalImportedWhy":"Uploaded answer key: Prolonged hyperglycemia can damage beta cells, reducing the likelihood of remission.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-021","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #21","q":"What are appropriate treatment goals for a newly diagnosed diabetic cat?","options":["Maintain mild hyperglycemia indefinitely.","Eliminate endogenous insulin secretion.","Prevent all fluctuations in blood glucose.","Control signs, avoid hypoglycemia and ketoacidosis, and pursue remission when achievable."],"answer":3,"why":"Quality of life and safe glycemic control are priorities. Some cats achieve remission after improved insulin sensitivity and recovery from glucotoxicity, but remission is not guaranteed, and avoiding severe hypoglycemia is essential.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":21,"originalImportedQuestion":"What is the primary therapeutic goal when treating a newly diagnosed diabetic cat?","originalImportedAnswer":"Achieve diabetic remission while avoiding dangerous complications.","originalImportedWhy":"Uploaded answer key: Achieve diabetic remission while avoiding dangerous complications."},{"id":"pharm-e2-user-diabetes-mcq-022","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #22","q":"Which combination best describes the major treatment goals for diabetic dogs?","options":["Achieve permanent remission and discontinue insulin.","Control clinical signs and prevent complications such as DKA and hypoglycemia.","Maintain blood glucose below 70 mg/dL.","Increase endogenous insulin production through dietary modification alone."],"answer":1,"why":"Uploaded answer key: Control clinical signs and prevent complications such as DKA and hypoglycemia.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":22},{"id":"pharm-e2-user-diabetes-mcq-023","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #23","q":"Why is diabetic remission generally less likely in dogs than in cats?","options":["Dogs lack insulin receptors.","Dogs cannot utilize exogenous insulin.","Dogs typically have substantial irreversible loss of insulin-producing beta cells.","Dogs metabolize glucose independently of insulin."],"answer":2,"why":"Most diabetic dogs have insufficient pancreatic insulin-secretory reserve and require ongoing replacement. Cats more often retain potentially recoverable beta-cell function after glucotoxicity and insulin resistance improve.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":23,"originalImportedWhy":"Uploaded answer key: Dogs typically have substantial irreversible loss of insulin-producing beta cells.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-024","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #24","q":"How does exogenous insulin improve glycemic regulation in cats with Type 2 diabetes?","options":["It stimulates insulin receptors that remain functional despite reduced sensitivity.","It permanently eliminates insulin resistance after one injection.","It destroys glucagon-producing alpha cells.","It prevents glucose absorption from the gastrointestinal tract."],"answer":0,"why":"Exogenous insulin still activates functioning receptors in insulin-resistant tissues, increasing glucose use and suppressing hepatic glucose production/ketogenesis. Greater insulin resistance can require individualized dosing and monitoring.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":24,"originalImportedWhy":"Uploaded answer key: It stimulates insulin receptors that remain functional despite reduced sensitivity.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-025","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #25","q":"What is the primary function of excipients in insulin preparations?","options":["Increase insulin production by pancreatic beta cells","Prevent insulin from binding to receptors","Increase glucose excretion through the kidneys","Modify insulin absorption and duration of action"],"answer":3,"why":"Added protamine, zinc or chemical changes slow insulin release from subcutaneous tissue, rather than changing the basic insulin receptor mechanism. Duration cannot be inferred solely from the drug's name.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":25,"originalImportedWhy":"Uploaded answer key: Modify insulin absorption and duration of action","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-026","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #26","q":"Why is regular insulin particularly useful during diabetic ketoacidosis?","options":["It contains large crystals that remain at the injection site.","It lacks absorption-modifying excipients and permits flexible IV or IM administration.","It cannot cause hypoglycemia.","It has a longer duration than all other insulin preparations."],"answer":1,"why":"Regular insulin is soluble short-acting insulin suitable for carefully monitored IV infusion or repeated IM protocols in DKA. It suppresses ketogenesis while fluids and electrolytes are corrected; it can still cause hypoglycemia and hypokalemia.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":26,"originalImportedQuestion":"Why is regular insulin particularly useful during diabetic ketoacidosis?","originalImportedAnswer":"It lacks absorption-modifying excipients and permits flexible IV or IM administration.","originalImportedWhy":"Uploaded answer key: It lacks absorption-modifying excipients and permits flexible IV or IM administration."},{"id":"pharm-e2-user-diabetes-mcq-027","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #27","q":"According to the lecture, why should excipient-containing insulin preparations generally be administered subcutaneously?","options":["Excipients require hepatic activation.","Insulin receptors are present only in subcutaneous tissues.","Their excipients may not be safe or effective when administered IV or IM.","Intravenous insulin cannot lower blood glucose."],"answer":2,"why":"Suspensions and depot formulations are made for subcutaneous release, not direct vascular delivery; administration by an unapproved route can radically change the exposure profile. Regular soluble insulin is used under monitored hospital protocols for DKA.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":27,"originalImportedWhy":"Uploaded answer key: Their excipients may not be safe or effective when administered IV or IM.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-028","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #28","q":"Which statement regarding porcine and canine insulin is correct?","options":["Their amino acid sequences are identical.","Porcine insulin cannot activate canine insulin receptors.","Porcine insulin differs from canine insulin by approximately 20%.","Canine insulin is structurally identical to feline insulin."],"answer":0,"why":"Uploaded answer key: Their amino acid sequences are identical.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":28},{"id":"pharm-e2-user-diabetes-mcq-029","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #29","q":"Which insulin preparation specifically contains porcine insulin?","options":["Humulin R","Insulin glargine","Insulin detemir","Vetsulin"],"answer":3,"why":"Uploaded answer key: Vetsulin","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":29},{"id":"pharm-e2-user-diabetes-mcq-030","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #30","q":"Why can human insulin preparations effectively treat diabetic dogs and cats despite species differences in amino acid sequences?","options":["Human insulin is converted into species-specific insulin by the liver.","Human insulin can activate canine and feline insulin receptors.","Species differences prevent insulin receptor binding.","Human insulin works exclusively through glucagon receptors."],"answer":1,"why":"Insulin receptor binding tolerates some sequence differences across mammalian species. Therapeutic activity depends on receptor activation and pharmacokinetics; a compatible sequence does not imply identical dosing.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":30,"originalImportedWhy":"Uploaded answer key: Human insulin can activate canine and feline insulin receptors.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-031","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #31","q":"Which statement best distinguishes amorphous from crystalline insulin preparations?","options":["Amorphous insulin contains no active peptide.","Crystalline insulin is always administered intravenously.","Amorphous insulin consists of non-coordinated molecules, whereas crystalline insulin has an organized molecular arrangement.","Crystalline insulin cannot bind insulin receptors."],"answer":2,"why":"Uploaded answer key: Amorphous insulin consists of non-coordinated molecules, whereas crystalline insulin has an organized molecular arrangement.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":31},{"id":"pharm-e2-user-diabetes-mcq-032","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #32","q":"How does insulin crystallization affect absorption following subcutaneous administration?","options":["It generally slows absorption because insulin must dissociate or dissolve before becoming available.","It causes immediate absorption into the bloodstream.","It prevents insulin from producing any pharmacologic activity.","It eliminates the possibility of hypoglycemia."],"answer":0,"why":"Crystalline particles must dissolve before insulin can enter the circulation; slower dissolution generally prolongs absorption from an SQ depot. Other formulation factors also influence onset and duration.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":32,"originalImportedWhy":"Uploaded answer key: It generally slows absorption because insulin must dissociate or dissolve before becoming available.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-033","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #33","q":"What is the role of protamine in insulin preparations?","options":["Directly activate GLUT4 receptors","Stimulate glucagon secretion","Increase renal glucose excretion","Bind insulin and promote crystallization, slowing absorption"],"answer":3,"why":"Protamine forms complexes with insulin that dissolve more slowly after injection. NPH and PZI both use this principle but have different formulations and time-action profiles.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":33,"originalImportedWhy":"Uploaded answer key: Bind insulin and promote crystallization, slowing absorption","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-034","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #34","q":"What does the term isophane (NPH) insulin refer to?","options":["Insulin conjugated to a fatty acid","An intermediate-acting protamine-containing insulin suspension","Insulin without absorption-modifying excipients","An insulin preparation containing no protein component"],"answer":1,"why":"NPH means neutral protamine Hagedorn. Protamine complexes insulin and delays its absorption from the subcutaneous depot; NPH is not defined merely by 'dilute protamine'.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":34,"originalImportedQuestion":"Which description of isophane insulin is correct according to the lecture?","originalImportedAnswer":"An insulin preparation containing dilute protamine","originalImportedWhy":"Uploaded answer key: An insulin preparation containing dilute protamine"},{"id":"pharm-e2-user-diabetes-mcq-035","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #35","q":"How does zinc contribute to prolonged insulin activity?","options":["It increases pancreatic insulin synthesis.","It blocks insulin receptors temporarily.","It promotes insulin crystallization and formation of molecular complexes such as hexamers.","It prevents insulin metabolism by the kidneys."],"answer":2,"why":"Zinc stabilizes insulin association into hexamers and crystalline structures. Since only released insulin can be absorbed readily, the depot's dissolution rate influences the duration.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":35,"originalImportedWhy":"Uploaded answer key: It promotes insulin crystallization and formation of molecular complexes such as hexamers.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-036","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #36","q":"Which mechanism explains the prolonged action of insulin preparations containing conjugated myristic acid?","options":["Myristic acid promotes albumin binding, allowing insulin to be released gradually.","Myristic acid directly blocks renal glucose reabsorption.","Myristic acid stimulates beta-cell proliferation.","Myristic acid prevents insulin from interacting with any plasma proteins."],"answer":0,"why":"Detemir carries a fatty-acid side chain that permits reversible albumin binding, acting as a circulating reservoir and delaying insulin availability.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":36,"originalImportedWhy":"Uploaded answer key: Myristic acid promotes albumin binding, allowing insulin to be released gradually.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-037","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #37","q":"Which insulin classification has an approximate onset of 5-15 minutes and duration of 2-4 hours according to the lecture?","options":["Intermediate-acting","Long-acting","Short-acting","Rapid-acting"],"answer":3,"why":"Uploaded answer key: Rapid-acting","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":37},{"id":"pharm-e2-user-diabetes-mcq-038","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #38","q":"Which pair of insulin analogs is classified as rapid-acting?","options":["Glargine and detemir","Lispro and aspart","NPH and PZI","Vetsulin and Ultralente"],"answer":1,"why":"Uploaded answer key: Lispro and aspart","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":38},{"id":"pharm-e2-user-diabetes-mcq-039","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #39","q":"What is the approximate duration of short-acting insulin in the lecture's classification?","options":["30-60 minutes","24-36 hours","5-8 hours","36-42 hours"],"answer":2,"why":"Uploaded answer key: 5-8 hours","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":39},{"id":"pharm-e2-user-diabetes-mcq-040","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #40","q":"Which insulin preparation is the principal short-acting insulin used in veterinary medicine?","options":["Regular insulin (Humulin R)","Insulin glargine","Protamine-zinc insulin","Insulin degludec"],"answer":0,"why":"Uploaded answer key: Regular insulin (Humulin R)","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":40},{"id":"pharm-e2-user-diabetes-mcq-041","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #41","q":"What causes the intermediate absorption profile of NPH insulin?","options":["Myristic acid-mediated albumin binding","Exclusive conversion to glucose in the liver","Absence of all formulation modifiers","Protamine-containing insulin complexes that delay release after subcutaneous injection"],"answer":3,"why":"NPH is a protamine-associated intermediate-acting insulin formulation. Its action is prolonged by delayed dissolution and absorption of insulin from the subcutaneous depot; do not confuse it with the zinc-based lente or fatty-acylated detemir mechanisms.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":41,"originalImportedQuestion":"Which combination correctly describes NPH insulin?","originalImportedAnswer":"Isophane/protamine and zinc","originalImportedWhy":"Uploaded answer key: Isophane/protamine and zinc"},{"id":"pharm-e2-user-diabetes-mcq-042","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #42","q":"What is the composition of Humulin 70/30?","options":["70% regular insulin and 30% glargine","70% NPH insulin and 30% regular insulin","70% zinc insulin and 30% detemir","70% protamine-zinc insulin and 30% degludec"],"answer":1,"why":"Uploaded answer key: 70% NPH insulin and 30% regular insulin","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":42},{"id":"pharm-e2-user-diabetes-mcq-043","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #43","q":"Which statement describes Vetsulin (porcine lente insulin)?","options":["It is an ultra-long-acting human insulin analog.","It contains only unmodified regular insulin.","It is a porcine zinc-insulin suspension containing amorphous and crystalline fractions.","It contains insulin conjugated to myristic acid."],"answer":2,"why":"Vetsulin is a porcine lente zinc-insulin suspension with approximately 35% amorphous and 65% crystalline insulin. The amorphous fraction is absorbed faster, while the crystalline fraction lasts longer. The original answer's '65% zinc-insulin and 35% regular insulin' labels were inaccurate.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":43,"originalImportedQuestion":"Which statement accurately describes Vetsulin?","originalImportedAnswer":"It contains approximately 65% zinc-insulin and 35% regular insulin.","originalImportedWhy":"Uploaded answer key: It contains approximately 65% zinc-insulin and 35% regular insulin."},{"id":"pharm-e2-user-diabetes-mcq-044","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #44","q":"What does the term Lente refer to in the context of insulin formulations?","options":["A zinc-associated insulin preparation with delayed absorption","A preparation containing only amorphous insulin","A rapid-acting insulin analog administered with meals","An insulin that works by inhibiting SGLT2"],"answer":0,"why":"Uploaded answer key: A zinc-associated insulin preparation with delayed absorption","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":44},{"id":"pharm-e2-user-diabetes-mcq-045","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #45","q":"Which handling instruction distinguishes Vetsulin from most other insulin preparations in the lecture?","options":["It must be frozen between uses.","It must always be administered intravenously.","It should never be mixed before administration.","It should be shaken vigorously before use, whereas most other preparations are gently rolled."],"answer":3,"why":"Vetsulin is a porcine zinc-insulin suspension and should be shaken according to its current product label to resuspend the insulin uniformly. Different insulins have different handling requirements; never generalize shaking instructions across formulations.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":45,"originalImportedQuestion":"Which handling instruction distinguishes Vetsulin from most other insulin preparations in the lecture?","originalImportedAnswer":"It should be shaken vigorously before use, whereas most other preparations are gently rolled.","originalImportedWhy":"Uploaded answer key: It should be shaken vigorously before use, whereas most other preparations are gently rolled."},{"id":"pharm-e2-user-diabetes-mcq-046","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #46","q":"What is the primary difference between Lente and Ultralente insulin?","options":["Ultralente contains no zinc.","Ultralente has larger insulin crystals and a higher zinc concentration.","Lente is a human insulin analog with three amino acid substitutions.","Ultralente contains only regular insulin."],"answer":1,"why":"Uploaded answer key: Ultralente has larger insulin crystals and a higher zinc concentration.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":46},{"id":"pharm-e2-user-diabetes-mcq-047","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #47","q":"What does PZI stand for?","options":["Pancreatic zinc inhibitor","Prolonged zinc isophane","Protamine-zinc insulin","Porcine zinc infusion"],"answer":2,"why":"Uploaded answer key: Protamine-zinc insulin","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":47},{"id":"pharm-e2-user-diabetes-mcq-048","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #48","q":"Why does PZI generally have a longer duration than NPH insulin?","options":["PZI contains higher concentrations of protamine and zinc.","PZI contains no excipients.","PZI is administered intravenously.","PZI stimulates endogenous insulin secretion."],"answer":0,"why":"PZI is a protamine- and zinc-containing suspension with prolonged absorption in suitable veterinary patients. Duration differs by formulation and species; it should never be substituted unit-for-unit without a monitored plan.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":48,"reviewFlag":"Course-specific wording or treatment recommendation: retain original for exam study; verify against current species-specific clinical guidance before patient use.","originalImportedWhy":"Uploaded answer key: PZI contains higher concentrations of protamine and zinc.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-049","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #49","q":"Which statement regarding PZI is consistent with the lecture?","options":["It is exclusively labeled for human use.","It contains only porcine insulin.","It is available only at 100 U/mL.","It is a veterinary-specific preparation available at 40 U/mL."],"answer":3,"why":"Uploaded answer key: It is a veterinary-specific preparation available at 40 U/mL.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":49},{"id":"pharm-e2-user-diabetes-mcq-050","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #50","q":"Which long-acting insulin analog is commonly used in feline diabetes and forms a subcutaneous depot by pH-dependent precipitation?","options":["Regular insulin","Insulin glargine","Humulin 70/30","Lispro"],"answer":1,"why":"Glargine is soluble in an acidic formulation and precipitates at near-physiologic tissue pH, allowing gradual insulin release. Its role as a common feline treatment is supported by published clinical experience, but choice should be individualized rather than framed as universally first-line.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":50,"originalImportedQuestion":"Which long-acting insulin is identified as a preferred first-choice preparation for diabetic cats in the lecture?","originalImportedAnswer":"Insulin glargine","originalImportedWhy":"Uploaded answer key: Insulin glargine"},{"id":"pharm-e2-user-diabetes-mcq-051","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #51","q":"What structural modification distinguishes insulin glargine from ordinary human insulin?","options":["Addition of zinc without any amino acid substitutions","Conjugation of myristic acid to a lysine residue","Alteration of three amino acids, changing its isoelectric point and solubility","Complete replacement of its A chain with bovine insulin"],"answer":2,"why":"Uploaded answer key: Alteration of three amino acids, changing its isoelectric point and solubility","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":51},{"id":"pharm-e2-user-diabetes-mcq-052","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #52","q":"Why does insulin glargine produce prolonged activity after subcutaneous administration?","options":["It becomes relatively insoluble at physiologic tissue pH, forming a precipitate that releases insulin slowly.","It stimulates the pancreas to continuously release insulin.","It permanently binds to circulating glucose.","It blocks hepatic insulin metabolism."],"answer":0,"why":"Glargine is formulated at acidic pH and forms subcutaneous microprecipitates at physiologic pH. Insulin then dissolves gradually, creating a longer, often flatter time-action profile.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":52,"originalImportedWhy":"Uploaded answer key: It becomes relatively insoluble at physiologic tissue pH, forming a precipitate that releases insulin slowly.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-053","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #53","q":"Which combination correctly describes the solubility of glargine according to the lecture?","options":["Highly soluble at pH 7.4 and insoluble at pH 4","Equally soluble at pH 4 and 7.4","Insoluble at all physiologic pH values","Approximately 95% soluble at pH 4 and 5% soluble at pH 7.4"],"answer":3,"why":"Uploaded answer key: Approximately 95% soluble at pH 4 and 5% soluble at pH 7.4","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":53},{"id":"pharm-e2-user-diabetes-mcq-054","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #54","q":"Why should insulin glargine not be casually diluted with ordinary solutions?","options":["Dilution permanently activates insulin receptors.","Changing its formulation pH can alter precipitation and absorption characteristics.","Dilution converts glargine into porcine insulin.","Dilution causes immediate destruction of pancreatic beta cells."],"answer":1,"why":"Dilution can change glargine's acidic vehicle and therefore the precipitation mechanism that produces slow release. It may alter exposure unpredictably.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":54,"originalImportedWhy":"Uploaded answer key: Changing its formulation pH can alter precipitation and absorption characteristics.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-055","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #55","q":"Which mechanism is responsible for the prolonged action of insulin detemir?","options":["Zinc-mediated formation of large insulin crystals","Direct inhibition of hepatic gluconeogenesis","Binding to albumin through a conjugated myristic acid group","Permanent insulin receptor activation"],"answer":2,"why":"Uploaded answer key: Binding to albumin through a conjugated myristic acid group","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":55,"reviewFlag":"Course-specific wording or treatment recommendation: retain original for exam study; verify against current species-specific clinical guidance before patient use."},{"id":"pharm-e2-user-diabetes-mcq-056","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #56","q":"Why does the lecture emphasize particular caution when administering detemir to diabetic dogs?","options":["Detemir has substantial activity at canine insulin receptors and may cause severe hypoglycemia.","Detemir cannot bind canine insulin receptors.","Detemir is rapidly destroyed by canine gastric acid after injection.","Detemir increases glucagon secretion in dogs."],"answer":0,"why":"Detemir has marked potency in dogs compared with some other formulations. Dose conversion must be individualized, with attention to hypoglycemia and product concentration—not simply copied from a human regimen.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":56,"originalImportedWhy":"Uploaded answer key: Detemir has substantial activity at canine insulin receptors and may cause severe hypoglycemia.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-057","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #57","q":"Which additional property of detemir is highlighted in the lecture?","options":["It produces permanent pancreatic beta-cell regeneration.","It prevents urinary tract infections.","It eliminates the need for dietary management.","It may promote weight loss."],"answer":3,"why":"Uploaded answer key: It may promote weight loss.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":57},{"id":"pharm-e2-user-diabetes-mcq-058","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #58","q":"Which mechanism best explains the prolonged action of insulin degludec?","options":["Immediate absorption of individual insulin monomers","Formation of multi-hexamer complexes that slowly dissociate into smaller complexes and monomers","Direct activation of pancreatic beta cells","Inhibition of renal glucose reabsorption"],"answer":1,"why":"Uploaded answer key: Formation of multi-hexamer complexes that slowly dissociate into smaller complexes and monomers","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":58},{"id":"pharm-e2-user-diabetes-mcq-059","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #59","q":"According to the lecture, approximately how long can insulin degludec act in humans?","options":["2-4 hours","8-12 hours","Up to 42 hours","Approximately 6 hours"],"answer":2,"why":"Uploaded answer key: Up to 42 hours","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":59},{"id":"pharm-e2-user-diabetes-mcq-060","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #60","q":"Which insulin is described as producing relatively few pronounced blood glucose nadirs?","options":["Degludec","Regular insulin","NPH insulin","Lispro"],"answer":0,"why":"Uploaded answer key: Degludec","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":60},{"id":"pharm-e2-user-diabetes-mcq-061","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #61","q":"Why is the absence of obvious hypoglycemic signs in a diabetic cat not sufficient evidence that its insulin dose is safe?","options":["Cats cannot become hypoglycemic.","Feline blood glucose does not respond to insulin.","All cats become hyperglycemic after insulin administration.","Cats may experience hypoglycemia without displaying obvious clinical signs."],"answer":3,"why":"Cats can have clinically silent low glucose. Home curves or CGM can identify low nadirs despite an apparently bright patient, preventing iatrogenic neurologic injury.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":61,"originalImportedWhy":"Uploaded answer key: Cats may experience hypoglycemia without displaying obvious clinical signs.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-062","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #62","q":"Which statement best describes insulin duration across species according to the lecture?","options":["Insulin always lasts longer in cats than in humans.","Duration is generally shorter in dogs than humans and may be even shorter in cats.","Insulin duration is identical in all mammals.","Insulin duration is unrelated to species."],"answer":1,"why":"Uploaded answer key: Duration is generally shorter in dogs than humans and may be even shorter in cats.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":62},{"id":"pharm-e2-user-diabetes-mcq-063","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #63","q":"Which insulin is mentioned as an older alternative in the uploaded lecture if PZI becomes unavailable?","options":["Lispro","Regular insulin","Ultralente","Humulin 70/30"],"answer":2,"why":"The historical lecture names ultralente; this is not a recommendation to substitute it in current veterinary practice. Product availability and current diabetes guidelines should determine actual treatment.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":63,"originalImportedQuestion":"Which insulin is specifically discussed as a potential alternative if PZI becomes unavailable?","originalImportedAnswer":"Ultralente","originalImportedWhy":"Uploaded answer key: Ultralente"},{"id":"pharm-e2-user-diabetes-mcq-064","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #64","q":"Which insulin preparation is described as having a distinctive pH-dependent precipitation mechanism rather than relying primarily on zinc crystallization or albumin binding?","options":["Glargine","NPH","Vetsulin","PZI"],"answer":0,"why":"Uploaded answer key: Glargine","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":64},{"id":"pharm-e2-user-diabetes-mcq-065","lecture":"Lecture 10","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #65","q":"Which statement best explains why insulin degludec might be considered for feline diabetes in the future, according to the lecture?","options":["It permanently cures Type 1 diabetes.","It contains no insulin peptide.","It is the only insulin that can be administered orally.","Its prolonged activity may make it a useful alternative if other preferred long-acting preparations become unavailable."],"answer":3,"why":"Uploaded answer key: Its prolonged activity may make it a useful alternative if other preferred long-acting preparations become unavailable.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":65},{"id":"pharm-e2-user-diabetes-mcq-066","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #66","q":"Why does the lecture recommend initiating most uncomplicated diabetic dogs and cats on twice-daily insulin therapy?","options":["Twice-daily administration eliminates the need for monitoring.","Most animals ultimately require twice-daily treatment, and switching from high-dose once-daily therapy may increase complications.","Insulin cannot be absorbed if given once daily.","Twice-daily insulin permanently restores beta-cell function."],"answer":1,"why":"Twice-daily schedules often provide better coverage when an insulin's effective duration is shorter than 24 hours in that individual animal. Use curves, clinical signs and product guidance rather than applying a universal schedule without assessment.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":66,"originalImportedWhy":"Uploaded answer key: Most animals ultimately require twice-daily treatment, and switching from high-dose once-daily therapy may increase complications.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-067","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #67","q":"How does the lecture distinguish initial insulin dosing approaches between dogs and cats?","options":["Both species are always dosed per kilogram.","Dogs are dosed per animal, while cats are dosed per kilogram.","Dogs are generally dosed on a per-kilogram basis, while cats are dosed on a per-cat basis.","Cats do not require individualized dosing."],"answer":2,"why":"Uploaded answer key: Dogs are generally dosed on a per-kilogram basis, while cats are dosed on a per-cat basis.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":67,"reviewFlag":"Course-specific wording or treatment recommendation: retain original for exam study; verify against current species-specific clinical guidance before patient use."},{"id":"pharm-e2-user-diabetes-mcq-068","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #68","q":"Which insulin preparations are recommended as common first choices for uncomplicated diabetic dogs?","options":["NPH or Vetsulin","Lispro or aspart","Regular insulin or degludec","Metformin or glipizide"],"answer":0,"why":"Uploaded answer key: NPH or Vetsulin","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":68},{"id":"pharm-e2-user-diabetes-mcq-069","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #69","q":"Which group contains commonly used longer-acting insulins for feline diabetes?","options":["Regular insulin, lispro, and aspart","NPH, Humulin 70/30, and Vetsulin exclusively","Glipizide, glyburide, and metformin","Glargine, detemir, and PZI"],"answer":3,"why":"Glargine and protamine-zinc insulin are established feline choices; detemir has also been used but requires careful species-specific dosing. These drugs differ in absorption profiles and are not interchangeable unit-for-unit. Newer guidelines and SGLT2 options require individual patient assessment.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":69,"originalImportedQuestion":"Which combination represents the lecture's preferred insulin options for uncomplicated diabetic cats?","originalImportedAnswer":"Glargine, detemir, and PZI","originalImportedWhy":"Uploaded answer key: Glargine, detemir, and PZI"},{"id":"pharm-e2-user-diabetes-mcq-070","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #70","q":"During the early stages of insulin therapy, how frequently does the lecture suggest evaluating the need for dose adjustments?","options":["Every 12 hours regardless of glucose results","Approximately every 5-7 days, depending on clinical signs and monitoring","Once every six months","Only when the animal develops DKA"],"answer":1,"why":"Rapid dose escalation before an insulin's pattern is understood can produce hypoglycemia. Follow patient-specific curves or CGM, appetite and clinical trends rather than a rigid calendar alone.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":70,"originalImportedWhy":"Uploaded answer key: Approximately every 5-7 days, depending on clinical signs and monitoring","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-071","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #71","q":"Which combination is most appropriate for monitoring diabetic regulation?","options":["Body temperature and respiratory rate alone","Urine color and appetite alone","Blood glucose curves and/or fructosamine, combined with clinical evaluation","Serum calcium concentrations alone"],"answer":2,"why":"Blood-glucose curves show timing and depth of peaks/nadirs, whereas fructosamine estimates preceding average glucose exposure. Clinical signs, weight and owner observations help distinguish meaningful control from isolated measurements.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":71,"originalImportedWhy":"Uploaded answer key: Blood glucose curves and/or fructosamine, combined with clinical evaluation","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-072","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #72","q":"Which finding best indicates successful insulin therapy in an uncomplicated diabetic dog?","options":["Stable body weight, improved activity, resolution of major clinical signs, and acceptable glycemic regulation","Persistent polyuria and progressive weight loss","Continuous blood glucose below 60 mg/dL","Recurrent episodes of symptomatic hypoglycemia"],"answer":0,"why":"Uploaded answer key: Stable body weight, improved activity, resolution of major clinical signs, and acceptable glycemic regulation","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":72},{"id":"pharm-e2-user-diabetes-mcq-073","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #73","q":"How should glucose targets be interpreted in an insulin-treated diabetic dog or cat?","options":["All measurements must remain between 100 and 250 mg/dL without exception.","Any blood glucose above 100 mg/dL requires another insulin injection.","A single target number is more important than clinical signs or hypoglycemia.","Interpret glucose patterns, nadirs, clinical signs and species-specific guidelines together; avoid hypoglycemia rather than enforcing one fixed 24-hour range."],"answer":3,"why":"An individualized glucose target balances quality of life, clinical control and avoidance of hypoglycemia. A blanket 100–250 mg/dL at all times is not a universal safety threshold, especially with stress hyperglycemia in cats.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":73,"reviewFlag":"Fixed lecture glucose target replaced by individualized interpretation.","originalImportedQuestion":"What blood glucose range is identified as an ideal target throughout the day in the lecture?","originalImportedAnswer":"Approximately 100-250 mg/dL","originalImportedWhy":"Uploaded answer key: Approximately 100-250 mg/dL"},{"id":"pharm-e2-user-diabetes-mcq-074","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #74","q":"Why is a low-carbohydrate diet particularly important for newly diagnosed diabetic cats receiving glargine or detemir?","options":["It directly destroys insulin-resistant receptors.","It can improve glycemic regulation and increase the likelihood of diabetic remission.","It prevents the kidneys from metabolizing insulin.","It eliminates the possibility of future diabetes recurrence."],"answer":1,"why":"Carbohydrate restriction can reduce postprandial glucose excursions and insulin demand in suitable cats. Better glycemic control reduces glucotoxicity, potentially improving residual beta-cell secretion.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":74,"originalImportedWhy":"Uploaded answer key: It can improve glycemic regulation and increase the likelihood of diabetic remission.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-075","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #75","q":"Which period is emphasized as the most favorable window for diabetic remission in cats?","options":["After five years of treatment","Only during the first 24 hours","The first six months following diagnosis and treatment","Only after permanent beta-cell destruction"],"answer":2,"why":"Uploaded answer key: The first six months following diagnosis and treatment","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":75},{"id":"pharm-e2-user-diabetes-mcq-076","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #76","q":"Which finding in a cat receiving a previously appropriate maintenance insulin dose should raise concern for possible diabetic remission?","options":["Repeated hypoglycemia or unexpectedly reduced insulin requirements","Persistent severe hyperglycemia despite increasing doses","Progressive weight loss with polyuria","Increasing fructosamine concentrations"],"answer":0,"why":"Reduced insulin needs or documented low glucose during treatment can indicate recovering endogenous insulin secretion. Confirm trends and reassess dosing safely; do not assume a single low reading proves sustained remission.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":76,"originalImportedWhy":"Uploaded answer key: Repeated hypoglycemia or unexpectedly reduced insulin requirements","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-077","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #77","q":"Which statement regarding feline diabetic remission is correct?","options":["Remission guarantees diabetes will never recur.","Remission requires complete destruction of beta cells.","Remission occurs only in cats with pancreatic tumors.","Remission may be temporary, particularly if obesity, high-carbohydrate feeding, or glucocorticoid exposure returns."],"answer":3,"why":"Uploaded answer key: Remission may be temporary, particularly if obesity, high-carbohydrate feeding, or glucocorticoid exposure returns.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":77},{"id":"pharm-e2-user-diabetes-mcq-078","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #78","q":"A diabetic cat initially improves on insulin therapy but continues to require increasing doses. At what dose does the lecture recommend considering a more extensive investigation of treatment failure?","options":["Above 0.1 U/kg/dose","Above 1 U/kg/dose","Above 0.2 U/cat/day","Above 10 U/kg/dose"],"answer":1,"why":"Uploaded answer key: Above 1 U/kg/dose","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":78},{"id":"pharm-e2-user-diabetes-mcq-079","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #79","q":"A diabetic dog continues to demonstrate polyuria, polydipsia, and poor regulation despite receiving more than 1.5 U/kg/dose of insulin. Which approach is most appropriate according to the lecture?","options":["Automatically double the insulin dose.","Discontinue all monitoring.","Investigate underlying disease, administration problems, antibodies, and the Somogyi effect.","Assume the animal cannot respond to insulin."],"answer":2,"why":"Persistent PU/PD despite high reported doses may reflect incorrect injection technique, spoiled insulin, infection, endocrine insulin resistance or other causes. A high glucose value alone does not prove the historical Somogyi phenomenon; look for documented low glucose.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":79,"originalImportedWhy":"Uploaded answer key: Investigate underlying disease, administration problems, antibodies, and the Somogyi effect.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-080","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #80","q":"Which statement best distinguishes insulin therapy in dogs from treatment intended to achieve feline remission?","options":["Dogs are generally treated to control clinical signs and maintain quality of life, while cats may be treated more aggressively to achieve remission.","Dogs should always receive rapid-acting insulin with every meal.","Cats never require exogenous insulin.","Diabetic dogs have a greater likelihood of remission than cats."],"answer":0,"why":"Uploaded answer key: Dogs are generally treated to control clinical signs and maintain quality of life, while cats may be treated more aggressively to achieve remission.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":80},{"id":"pharm-e2-user-diabetes-mcq-081","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #81","q":"Which group of clinical signs is most consistent with insulin-associated hypoglycemia?","options":["Polyuria, polydipsia, and persistent hyperglycemia","Fever, coughing, and nasal discharge","Ascites, jaundice, and diarrhea exclusively","Weakness, hunger, depression, and potentially convulsions"],"answer":3,"why":"Uploaded answer key: Weakness, hunger, depression, and potentially convulsions","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":81},{"id":"pharm-e2-user-diabetes-mcq-082","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #82","q":"A conscious diabetic cat develops mild signs of hypoglycemia but remains able to eat. Which intervention is consistent with the lecture?","options":["Administer additional insulin immediately.","Offer food, including a carbohydrate-containing meal.","Withhold all food for 12 hours.","Administer a sulfonylurea."],"answer":1,"why":"A conscious hypoglycemic animal able to swallow can receive food or an appropriate oral glucose source while contacting veterinary care. Do not force-feed an obtunded patient because of aspiration risk; subsequent insulin dosing requires reassessment.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":82,"originalImportedQuestion":"A conscious diabetic cat develops mild signs of hypoglycemia but remains able to eat. Which intervention is consistent with the lecture?","originalImportedAnswer":"Offer food, including a carbohydrate-containing meal.","originalImportedWhy":"Uploaded answer key: Offer food, including a carbohydrate-containing meal."},{"id":"pharm-e2-user-diabetes-mcq-083","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #83","q":"A diabetic dog develops severe hypoglycemic signs and cannot swallow normally. Which immediate action is described in the lecture?","options":["Force a large volume of water into the mouth.","Administer another dose of long-acting insulin.","Apply a sugar-containing syrup or gel to the gums while arranging emergency veterinary care.","Wait until the next scheduled feeding."],"answer":2,"why":"Severe hypoglycemia can cause seizures, coma and loss of airway protection. Apply glucose gel/syrup to accessible oral mucosa without forcing swallowing while arranging immediate emergency care; definitive IV dextrose and monitoring may be needed.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":83,"originalImportedQuestion":"A diabetic dog develops severe hypoglycemic signs and cannot swallow normally. Which immediate action is described in the lecture?","originalImportedAnswer":"Apply a sugar-containing syrup or gel to the gums while arranging emergency veterinary care.","originalImportedWhy":"Uploaded answer key: Apply a sugar-containing syrup or gel to the gums while arranging emergency veterinary care."},{"id":"pharm-e2-user-diabetes-mcq-084","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #84","q":"Why is hypoglycemia especially dangerous in veterinary patients?","options":["Animals cannot reliably recognize their condition or independently obtain an appropriate carbohydrate snack.","Hypoglycemia never produces neurologic signs in animals.","Animals always compensate by increasing glucagon secretion sufficiently.","Hypoglycemia permanently improves insulin sensitivity."],"answer":0,"why":"The brain relies heavily on a continuous glucose supply. Severe hypoglycemia can cause neuroglycopenia, seizures and coma, while the patient cannot independently seek appropriate carbohydrate.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":84,"originalImportedWhy":"Uploaded answer key: Animals cannot reliably recognize their condition or independently obtain an appropriate carbohydrate snack.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-085","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #85","q":"Why should owners use a consistent general subcutaneous injection region?","options":["Insulin only works when injected over the thorax.","Injection location has no influence on insulin absorption.","Changing injection sites permanently destroys insulin.","Differences in regional blood flow can alter the rate of insulin absorption."],"answer":3,"why":"Local perfusion and tissue characteristics can alter subcutaneous insulin absorption. Consistent injection technique helps interpret glucose curves without confusing technique-related variability for disease progression.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":85,"originalImportedWhy":"Uploaded answer key: Differences in regional blood flow can alter the rate of insulin absorption.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-086","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #86","q":"Which client-related problem can cause persistent hyperglycemia despite an apparently appropriate prescribed insulin dose?","options":["Consistent insulin refrigeration","Accidentally injecting insulin into the fur instead of subcutaneous tissue","Using the correct syringe concentration","Consistent injection technique"],"answer":1,"why":"An injection delivered into hair rather than subcutaneous tissue does not reliably enter the patient. Checking equipment, technique and product handling is part of evaluating apparent treatment failure.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":86,"originalImportedWhy":"Uploaded answer key: Accidentally injecting insulin into the fur instead of subcutaneous tissue","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-087","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #87","q":"Why is it essential to match the syringe type to the insulin concentration?","options":["Syringe type changes insulin receptor affinity.","U-40 and U-100 syringes deliver identical volumes at the same numbered marking.","A concentration mismatch can result in substantial dosing errors and potentially dangerous hypoglycemia.","Insulin concentration does not affect delivered units."],"answer":2,"why":"U-40 and U-100 refer to units per mL. Matching the syringe graduations to the product prevents large volume errors; changing between concentrations is not a simple syringe swap.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":87,"originalImportedWhy":"Uploaded answer key: A concentration mismatch can result in substantial dosing errors and potentially dangerous hypoglycemia.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-088","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #88","q":"A veterinarian prescribes 4 units of U-40 insulin. What volume contains the prescribed dose?","options":["0.10 mL","0.04 mL","0.40 mL","1.00 mL"],"answer":0,"why":"Uploaded answer key: 0.10 mL","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":88},{"id":"pharm-e2-user-diabetes-mcq-089","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #89","q":"A diabetic dog receives 5 units of U-100 insulin. What volume is required?","options":["0.50 mL","0.20 mL","0.10 mL","0.05 mL"],"answer":3,"why":"Uploaded answer key: 0.05 mL","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":89},{"id":"pharm-e2-user-diabetes-mcq-090","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #90","q":"Which insulin storage recommendation is emphasized in the lecture?","options":["Freeze insulin to maintain potency.","Refrigerate insulin without freezing it and handle it according to the formulation's requirements.","Store all insulin preparations in direct sunlight.","Heat insulin before every injection."],"answer":1,"why":"Uploaded answer key: Refrigerate insulin without freezing it and handle it according to the formulation's requirements.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":90,"reviewFlag":"Course-specific wording or treatment recommendation: retain original for exam study; verify against current species-specific clinical guidance before patient use."},{"id":"pharm-e2-user-diabetes-mcq-091","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #91","q":"What does the historical term Somogyi effect describe?","options":["Progressive insulin resistance caused exclusively by obesity","Permanent pancreatic beta-cell regeneration","Rebound hyperglycemia following excessive insulin activity and a rapid fall in blood glucose","Increased insulin absorption caused by renal disease"],"answer":2,"why":"The proposed Somogyi effect describes rebound hyperglycemia after insulin-associated hypoglycemia and counterregulatory hormone release. Its clinical importance has been questioned, particularly in cats; 2025 iCatCare guidance reports no evidence for it in cats. Do not infer overdose from high glucose readings alone.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":91,"reviewFlag":"Historical lecture concept; avoid diagnosing a Somogyi effect in cats without documented hypoglycemia.","originalImportedQuestion":"What is the Somogyi effect?","originalImportedAnswer":"Rebound hyperglycemia following excessive insulin activity and a rapid fall in blood glucose","originalImportedWhy":"Uploaded answer key: Rebound hyperglycemia following excessive insulin activity and a rapid fall in blood glucose"},{"id":"pharm-e2-user-diabetes-mcq-092","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #92","q":"Which finding would most directly support suspected insulin-induced rebound hyperglycemia, rather than ordinary poor regulation?","options":["Documented hypoglycemia followed by increased glucose during serial or continuous monitoring","Consistently normal blood glucose without clinical signs","Persistent hypoglycemia without a subsequent increase","Hyperglycemia occurring only before the first insulin injection"],"answer":0,"why":"A low glucose nadir preceding hyperglycemia is the relevant sequence for the proposed rebound mechanism. A few days of apparently good regulation followed by poor regulation is nonspecific and cannot establish it. Feline evidence for this mechanism is especially weak.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":92,"originalImportedQuestion":"Which pattern is most suggestive of the Somogyi effect?","originalImportedAnswer":"One or two days of apparently good regulation followed by several days of poor regulation","originalImportedWhy":"Uploaded answer key: One or two days of apparently good regulation followed by several days of poor regulation"},{"id":"pharm-e2-user-diabetes-mcq-093","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #93","q":"What should the veterinarian do when insulin overdose or unrecognized hypoglycemia is suspected in a diabetic patient?","options":["Increase the insulin dose immediately.","Add a sulfonylurea without monitoring.","Discontinue all dietary management.","Verify glucose trends (preferably with CGM or a curve), assess clinical signs, and adjust insulin safely if hypoglycemia is documented."],"answer":3,"why":"Dose changes should be driven by the glucose nadir, clinical signs and documented hypoglycemia. Automatically reducing insulin for nonspecific hyperglycemia can lead to undertreatment; confirmed hypoglycemia requires prompt safety-focused management.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":93,"reviewFlag":"Course-specific wording or treatment recommendation: retain original for exam study; verify against current species-specific clinical guidance before patient use.","originalImportedQuestion":"What is the lecture's recommended initial response when the Somogyi effect is suspected?","originalImportedAnswer":"Reduce the insulin dose and reassess glycemic regulation within approximately 2-5 days.","originalImportedWhy":"Uploaded answer key: Reduce the insulin dose and reassess glycemic regulation within approximately 2-5 days."},{"id":"pharm-e2-user-diabetes-mcq-094","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #94","q":"Why may blood glucose curves be more difficult to interpret in cats than dogs?","options":["Cats lack circulating glucose.","Stress-associated hyperglycemia can distort feline blood glucose measurements.","Cats do not respond to exogenous insulin.","Blood glucose curves cannot detect hypoglycemia."],"answer":1,"why":"Stress catecholamines can raise feline glucose transiently, confusing clinic curves. Home trends/CGM, clinical signs and fructosamine can help distinguish stress hyperglycemia from sustained poor control.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":94,"reviewFlag":"Course-specific wording or treatment recommendation: retain original for exam study; verify against current species-specific clinical guidance before patient use.","originalImportedWhy":"Uploaded answer key: Stress-associated hyperglycemia can distort feline blood glucose measurements.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-095","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #95","q":"What does serum fructosamine represent?","options":["Glycosylated hemoglobin reflecting glucose regulation over several months","A pancreatic hormone that stimulates insulin release","Glycosylated albumin reflecting average glycemic regulation over approximately 2-3 weeks","A direct measurement of circulating insulin concentration"],"answer":2,"why":"Uploaded answer key: Glycosylated albumin reflecting average glycemic regulation over approximately 2-3 weeks","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":95},{"id":"pharm-e2-user-diabetes-mcq-096","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #96","q":"Which statement correctly compares fructosamine and hemoglobin A1C?","options":["Fructosamine reflects approximately 2-3 weeks of glycemia, while A1C reflects approximately 2-3 months.","Both measure blood glucose over the previous hour.","Fructosamine measures insulin antibodies, while A1C measures glucagon.","A1C is the principal routine veterinary test for short-term glucose fluctuations."],"answer":0,"why":"Uploaded answer key: Fructosamine reflects approximately 2-3 weeks of glycemia, while A1C reflects approximately 2-3 months.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":96},{"id":"pharm-e2-user-diabetes-mcq-097","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #97","q":"A diabetic cat has markedly increased insulin requirements and is diagnosed with an anterior pituitary tumor producing excess growth hormone. Which mechanism explains its insulin resistance?","options":["Growth hormone inhibits all hepatic glucose production.","Growth hormone directly destroys circulating glucose.","Growth hormone blocks intestinal carbohydrate absorption.","Growth hormone promotes hepatic gluconeogenesis and contributes to hyperglycemia."],"answer":3,"why":"Excess growth hormone antagonizes insulin action in peripheral tissues and promotes hepatic glucose output, causing marked insulin resistance. Cats with hypersomatotropism/acromegaly may require unusually high insulin doses, but diagnosis uses appropriate endocrine testing and clinical context.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":97,"originalImportedQuestion":"A diabetic cat has markedly increased insulin requirements and is diagnosed with an anterior pituitary tumor producing excess growth hormone. Which mechanism explains its insulin resistance?","originalImportedAnswer":"Growth hormone promotes hepatic gluconeogenesis and contributes to hyperglycemia.","originalImportedWhy":"Uploaded answer key: Growth hormone promotes hepatic gluconeogenesis and contributes to hyperglycemia."},{"id":"pharm-e2-user-diabetes-mcq-098","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #98","q":"Why might a cat with acromegaly receiving large insulin doses suddenly develop hypoglycemia?","options":["Acromegaly permanently prevents insulin absorption.","Growth hormone secretion may fluctuate, temporarily reducing insulin resistance while a high insulin dose remains in effect.","Pituitary tumors prevent all glucagon secretion.","Insulin is converted directly into glucose during treatment."],"answer":1,"why":"If insulin resistance falls while a previously high insulin dose persists, the patient can abruptly become hypoglycemic. Intercurrent endocrine disease and changing appetite/renal function also warrant monitoring.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":98,"originalImportedWhy":"Uploaded answer key: Growth hormone secretion may fluctuate, temporarily reducing insulin resistance while a high insulin dose remains in effect.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-099","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #99","q":"How can renal insufficiency affect exogenous insulin therapy?","options":["It increases insulin elimination and always requires higher doses.","It prevents insulin receptor activation.","Reduced renal insulin metabolism can prolong insulin activity and increase hypoglycemia risk.","It completely prevents subcutaneous insulin absorption."],"answer":2,"why":"Kidneys participate in insulin clearance; renal dysfunction can prolong insulin effect and increase hypoglycemia risk. Concurrent illness and altered intake can change requirements in either direction.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":99,"originalImportedWhy":"Uploaded answer key: Reduced renal insulin metabolism can prolong insulin activity and increase hypoglycemia risk.","rationaleStatus":"reviewed-mechanism"},{"id":"pharm-e2-user-diabetes-mcq-100","lecture":"Lecture 11","sourceGroup":"Lectures 10–11 · uploaded MCQ set","topic":"Diabetes multiple-choice · #100","q":"Which statement best describes anti-insulin antibodies in diabetic dogs and cats according to the lecture?","options":["They may involve IgG or IgM and should be considered when other causes of poor regulation have been investigated.","They are always IgE-mediated and cause immediate anaphylaxis.","They are the most common cause of diabetes mellitus.","They occur only with porcine insulin."],"answer":0,"why":"Uploaded answer key: They may involve IgG or IgM and should be considered when other causes of poor regulation have been investigated.","source":"User-supplied Diabetes Lectures 10–11 MCQs · Nov 20, 2026","exam":"Exam 2 · uploaded multiple-choice","sourceNumber":100}];
const ids=new Set(target.map(x=>x.id));for(const q of bank){if(!ids.has(q.id)){target.push(q);ids.add(q.id)}}
window.VPQ_PHARM_DIABETES_UPLOADED_MCQ_COUNT=bank.length;
})();
